action_details.action_postfix:
0.0 /id_additions xdef





result.id_state_taxes_deducted 0.0 ne
{
  id_additions result.id_state_taxes_deducted add /id_additions xdef
} if

id_additions /result.id_state_additions xdef


0.0 /id_subtractions xdef






result.id_us_interest_income 0.0 ne
{
  id_subtractions result.id_us_interest_income add /id_subtractions xdef
} if

result.id_municipal_interest 0.0 ne
{
  id_subtractions result.id_municipal_interest add /id_subtractions xdef
} if

id_subtractions /result.id_state_subtractions xdef

"Idaho additions: $" result.id_state_additions cvs strconcat ", subtractions: $" strconcat result.id_state_subtractions cvs strconcat job.audit_trail swap addto
